import{c as a,Q as n,j as e,m as i}from"./chunks/framework.DOi4mjdC.js";const g=JSON.parse('{"title":"InitV2","description":"","frontmatter":{},"headers":[{"level":1,"title":"InitV2","slug":"initv2"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/HCCL通信类/HCCL-Kernel侧接口/InitV2.md","filePath":"api/SIMD-API/高阶API/HCCL通信类/HCCL-Kernel侧接口/InitV2.md"}'),s={name:"api/SIMD-API/高阶API/HCCL通信类/HCCL-Kernel侧接口/InitV2.md"};function l(p,t,d,r,o,c){return n(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="initv2" tabindex="-1">InitV2 <a class="header-anchor" href="#initv2" aria-label="Permalink to &quot;InitV2&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>HCCL客户端初始化接口。该接口默认在所有核上工作，用户也可以在调用前通过<a href="./../../../基础API/系统变量访问/GetBlockIdx.html">GetBlockIdx</a>指定其在某一个核上运行。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline void InitV2(GM_ADDR context, const void *initTiling)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>context</td><td>输入</td><td>通信上下文，包含rankDim，rankID等相关信息。通过框架提供的获取通信上下文的接口GetHcclContext获取context。</td></tr><tr><td>initTiling</td><td>输入</td><td>通信域初始化Mc2InitTiling的地址。Mc2InitTiling在Host侧计算得出，具体请参考表1 Mc2InitTiling参数说明，由框架传递到Kernel函数中使用。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>本接口必须与<a href="./SetCcTilingV2.html">SetCcTilingV2</a>接口配合使用。</li><li>调用本接口时，必须使用标准C++语法定义TilingData结构体的开发方式。</li><li>调用本接口传入的initTiling参数，不能使用Global Memory地址，建议通过<a href="./../../../基础API/Kernel-Tiling/GET_TILING_DATA_WITH_STRUCT.html">GET_TILING_DATA_WITH_STRUCT</a>接口获取TilingData的栈地址。</li><li>本接口不支持使用相同的context初始化多个HCCL对象。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>用户自定义TilingData结构体：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>class UserCustomTilingData {</span></span>
<span class="line"><span>    AscendC::tiling::Mc2InitTiling initTiling;</span></span>
<span class="line"><span>    AscendC::tiling::Mc2CcTiling tiling;</span></span>
<span class="line"><span>    CustomTiling param;</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>在所有核上创建HCCL对象，并调用InitV2接口初始化：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>extern &quot;C&quot; __global__ __aicore__ void userKernel(GM_ADDR aGM, GM_ADDR workspaceGM, GM_ADDR tilingGM) {</span></span>
<span class="line"><span>    REGISTER_TILING_DEFAULT(UserCustomTilingData);</span></span>
<span class="line"><span>    GET_TILING_DATA_WITH_STRUCT(UserCustomTilingData,tilingData,tilingGM);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    GM_ADDR contextGM = AscendC::GetHcclContext&lt;0&gt;(); </span></span>
<span class="line"><span>    Hccl hccl;</span></span>
<span class="line"><span>    hccl.InitV2(contextGM, &amp;tilingData);</span></span>
<span class="line"><span>    hccl.SetCcTilingV2(offsetof(UserCustomTilingData, tiling));</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // 调用HCCL的Prepare、Commit、Wait、Finalize接口</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,19)])])}const u=a(s,[["render",l]]);export{g as __pageData,u as default};
